def feature(s):
    v = s.get('volume_per_atom_A3') or s.get('basic_structure_statistics', {}).get('volume_per_atom_A3') or 0.0
    if v <= 0.0 or not math.isfinite(v):
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        r = props.get(e, {}).get('covalent_radius_A')
        if x is not None and x > 0.0 and math.isfinite(x) and r is not None and r > 0.0 and math.isfinite(r):
            total += x * r * r * r
            weight += x
    if weight <= 0.0:
        return 0.0
    return float(4.0 * math.pi * total / (3.0 * weight * v))

def feature(s):
    v = s.get('volume_per_atom_A3') or s.get('basic_structure_statistics', {}).get('volume_per_atom_A3') or 0.0
    if v <= 0.0 or not math.isfinite(v):
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        z = props.get(e, {}).get('valence_electrons')
        if x is not None and x > 0.0 and math.isfinite(x) and z is not None and math.isfinite(z):
            total += x * z
            weight += x
    return float(total / (weight * v)) if weight > 0.0 else 0.0

def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    if n == 0:
        return 0.0
    nearest = [math.inf] * n
    for b in s.get('neighbors', ()):
        d = b.get('distance_A')
        if d is not None and d > 0.0 and math.isfinite(d):
            i = b['i']
            if d < nearest[i]:
                nearest[i] = d
    total = 0.0
    weight = 0.0
    for i in range(n):
        o = max(0.0, float(sites[i].get('occupancy', 1.0) or 0.0))
        if math.isfinite(nearest[i]) and o > 0.0:
            total += o * nearest[i]
            weight += o
    return float(total / weight) if weight > 0.0 else 0.0

def feature(s):
    sites = s.get('sites', ())
