    nearest = [math.inf] * n
    for b in s.get('neighbors', ()):
        d = b.get('distance_A')
        if d is not None and d > 0.0 and math.isfinite(d):
            i = b['i']
            if d < nearest[i]:
                nearest[i] = d
    a = 0.0
    q = 0.0
    w = 0.0
    for i in range(n):
        o = max(0.0, float(sites[i].get('occupancy', 1.0) or 0.0))
        if math.isfinite(nearest[i]) and o > 0.0:
            a += o * nearest[i]
            q += o * nearest[i] * nearest[i]
            w += o
    if w <= 0.0 or a <= 0.0:
        return 0.0
    mean = a / w
    return float(math.sqrt(max(0.0, q / w - mean * mean)) / mean)

def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    if n == 0:
        return 0.0
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    nearest = [math.inf] * n
    neighbors = s.get('neighbors', ())
    for b in neighbors:
        d = b.get('distance_A')
        if d is not None and d > 0.0 and math.isfinite(d):
            i = b['i']
            if d < nearest[i]:
                nearest[i] = d
    coordination = [0.0] * n
    for b in neighbors:
        d = b.get('distance_A')
        i = b['i']
        if d is not None and d > 0.0 and math.isfinite(d) and d <= 1.25 * nearest[i]:
            coordination[i] += occ[b['j']]
    w = sum(occ)
    return float(sum(occ[i] * coordination[i] for i in range(n)) / w) if w > 0.0 else 0.0

