    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    nearest = [math.inf] * n
    neighbors = s.get('neighbors', ())
    for b in neighbors:
        d = b.get('distance_A')
        if d is not None and d > 0.0 and math.isfinite(d):
            i = b['i']
            if d < nearest[i]:
                nearest[i] = d
    coordination = [0.0] * n
    for b in neighbors:
        d = b.get('distance_A')
        i = b['i']
        if d is not None and d > 0.0 and math.isfinite(d) and d <= 1.25 * nearest[i]:
            coordination[i] += occ[b['j']]
    w = sum(occ)
    if w <= 0.0:
        return 0.0
    mean = sum(occ[i] * coordination[i] for i in range(n)) / w
    if mean <= 0.0:
        return 0.0
    variance = sum(occ[i] * (coordination[i] - mean) ** 2 for i in range(n)) / w
    return float(math.sqrt(max(0.0, variance)) / mean)

def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    if n == 0:
        return 0.0
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    counts = {}
    for i in range(n):
        e = sites[i].get('element')
        counts[e] = counts.get(e, 0.0) + occ[i]
    population = sum(occ)
    if population <= 0.0:
        return 0.0
    expected = 1.0 - sum((x / population) ** 2 for x in counts.values())
    if expected <= 1e-12:
        return 0.0
    nearest = [math.inf] * n
    neighbors = s.get('neighbors', ())
    for b in neighbors:
        d = b.get('distance_A')
        if d is not None and d > 0.0 and math.isfinite(d):
            i = b['i']
            if d < nearest[i]:
                nearest[i] = d
    unlike = 0.0
    total = 0.0
    for b in neighbors:
        d = b.get('distance_A')
        i = b['i']
        j = b['j']
        if d is not None and d > 0.0 and math.isfinite(d) and d <= 1.25 * nearest[i]:
            w = occ[i] * occ[j]
            total += w
            if sites[i].get('element') != sites[j].get('element'):
                unlike += w
    return float(unlike / (total * expected)) if total > 0.0 else 0.0

def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    if n == 0:
        return 0.0
    props = s.get('element_properties', {})
    chi = [props.get(t.get('element'), {}).get('eneg') for t in sites]
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    population = sum(occ)
    if population <= 0.0:
        return 0.0
    nearest = [math.inf] * n
    neighbors = s.get('neighbors', ())
    for b in neighbors:
        d = b.get('distance_A')
        if d is not None and d > 0.0 and math.isfinite(d):
            i = b['i']
            if d < nearest[i]:
                nearest[i] = d
    total = 0.0
    for b in neighbors:
        d = b.get('distance_A')
        i = b['i']
        j = b['j']
        if d is None or d <= 0.0 or not math.isfinite(d) or d > 1.25 * nearest[i]:
            continue
        a = chi[i]
        c = chi[j]
        if a is None or c is None or not math.isfinite(a) or not math.isfinite(c):
            continue
        ionic = -math.expm1(-0.25 * (a - c) ** 2)
        total += occ[i] * occ[j] * ionic / d
    return float(0.5 * total / population)
